/* Menu-driven array operations: traverse, insert, delete, search, reverse, sort and frequency
 * Based on Computer Programming 1 Lab Manual.
 * Standard C (C99); compile with: gcc 20_all_array_operations_menu.c -o 20_all_array_operations_menu
 */
#include <stdio.h>
#define CAP 100
int main(void){int a[CAP],n,ch,x,p;printf("Number of initial values (0-100): ");if(scanf("%d",&n)!=1||n<0||n>CAP)return 1;for(int i=0;i<n;i++)scanf("%d",&a[i]);do{printf("\\n1 Display 2 Insert beginning 3 Insert position 4 Insert end 5 Delete position 6 Delete value 7 Search 8 Reverse 9 Sort 10 Frequency 0 Exit\\nChoice: ");scanf("%d",&ch);switch(ch){case 1:for(int i=0;i<n;i++)printf("%d ",a[i]);puts("");break;case 2:if(n==CAP)puts("Full");else{scanf("%d",&x);for(int i=n;i>0;i--)a[i]=a[i-1];a[0]=x;n++;}break;case 3:if(n==CAP)puts("Full");else{scanf("%d%d",&p,&x);if(p<1||p>n+1)puts("Invalid position");else{for(int i=n;i>=p;i--)a[i]=a[i-1];a[p-1]=x;n++;}}break;case 4:if(n==CAP)puts("Full");else{scanf("%d",&x);a[n++]=x;}break;case 5:scanf("%d",&p);if(p<1||p>n)puts("Invalid position");else{for(int i=p;i<n;i++)a[i-1]=a[i];n--;}break;case 6:scanf("%d",&x);for(p=0;p<n&&a[p]!=x;p++);if(p==n)puts("Not found");else{for(int i=p+1;i<n;i++)a[i-1]=a[i];n--;}break;case 7:scanf("%d",&x);for(p=0;p<n&&a[p]!=x;p++);if(p==n)puts("Not found");else printf("Found at position %d\\n",p+1);break;case 8:for(int i=0;i<n/2;i++){x=a[i];a[i]=a[n-1-i];a[n-1-i]=x;}break;case 9:for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(a[i]>a[j]){x=a[i];a[i]=a[j];a[j]=x;}break;case 10:for(int i=0;i<n;i++){int seen=0;for(int k=0;k<i;k++)if(a[k]==a[i])seen=1;if(!seen){int c=0;for(int j=0;j<n;j++)if(a[j]==a[i])c++;printf("%d: %d\\n",a[i],c);}}break;case 0:break;default:puts("Invalid choice");}}while(ch!=0);return 0;}
